  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='menu'){const open=document.body.classList.toggle('menu-open');b.setAttribute('aria-expanded',open?'true':'false');return;}if(a==='logout'){setCurrent(null);save();location.hash='home';flash('Signed out.');return;}if(a==='new-listing'){location.hash='new-listing';return;}if(a==='remove-food-photo'){e.preventDefault();const form=b.closest('form');if(form){form.elements.photoData.value='';const input=form.querySelector('input[name="foodPhoto"]'),preview=form.querySelector('[data-photo-preview]'),wrap=form.querySelector('[data-photo-preview-wrap]'),status=form.querySelector('[data-photo-status]');if(input)input.value='';if(preview)preview.removeAttribute('src');if(wrap)wrap.hidden=true;if(status)status.textContent='Photo removed. A stock food photo will be used.';}return;}if(a==='use-current-location'){e.preventDefault();const form=b.closest('form'),status=form?.querySelector('[data-location-status]'),lat=form?.elements.latitude,lon=form?.elements.longitude;if(!navigator.geolocation){if(status)status.textContent='Location is unavailable in this browser. Enter the address manually.';return;}b.disabled=true;if(status)status.textContent='Finding your location…';navigator.geolocation.getCurrentPosition(position=>{const latitude=position.coords.latitude,longitude=position.coords.longitude;if(lat)lat.value=latitude;if(lon)lon.value=longitude;if(status)status.textContent=`Map pin saved: ${latitude.toFixed(5)}, ${longitude.toFixed(5)}. Please confirm the pickup address above.`;b.disabled=false;},error=>{if(status)status.textContent=error.code===1?'Location permission was denied. Enter the pickup address manually.':'Could not get your location. Check location permission and try again.';b.disabled=false;},{enableHighAccuracy:true,timeout:15000,maximumAge:30000});return;}if(a.startsWith('resolve-')){const r=data.reports.find(x=>x.id===a.slice(8));if(r){r.status='Reviewed';const l=data.listings.find(x=>x.id===r.listingId);if(l&&l.status==='Flagged for Review')l.status='Available';log('Reviewed a listing report');save();render();flash('Report review recorded.');}return;}if(a.startsWith('request-')){const lid=a.slice(8),l=data.listings.find(x=>x.id===lid),u=user();if(u.accessApproved===false||!u.verified){flash('Your organization must be approved before it can request food.','error');return;}if(!l||l.status!=='Available'||new Date(l.deadline)<=new Date()){flash('This listing is no longer available.','error');return;}const pickupLocation=document.getElementById('request-location')?.value.trim();if(!pickupLocation){flash('Enter your organization pickup place before requesting this food.','error');return;}if(data.reservations.some(r=>r.listingId===lid&&r.recipientId===u.id&&!['Declined','Cancelled'].includes(r.status))){flash('You already requested this listing.','error');return;}data.reservations.push({id:id(),listingId:lid,recipientId:u.id,pickupLocation,note:document.getElementById('request-note')?.value.trim()||'',status:'Pending',donorPickup:false,recipientPickup:false});log(`Requested ${l.item}`);save();render();flash('Order request sent to the donor. They must accept before pickup; both sides confirm the handover.');return;}if(a.startsWith('accept-')||a.startsWith('decline-')){const [verb,rid]=a.split('-'),r=data.reservations.find(x=>x.id===rid),l=data.listings.find(x=>x.id===r?.listingId);if(!r||!l)return;if(verb==='accept'){if(l.status!=='Available'){flash('This listing is no longer available.','error');return;}r.status='Confirmed';l.status='Reserved';data.reservations.filter(x=>x.listingId===l.id&&x.id!==r.id&&x.status==='Pending').forEach(x=>x.status='Declined');log(`Confirmed reservation for ${l.item}`);flash('Order accepted. The recipient can now confirm collection. Other pending requests were closed.');}else{r.status='Declined';log('Declined a reservation');flash('Request declined.');}save();render();return;}if(a.startsWith('pickup-')){const r=data.reservations.find(x=>x.id===a.slice(7)),l=data.listings.find(x=>x.id===r?.listingId),u=user();if(!r||r.status!=='Confirmed')return;if(u.role==='donor')r.donorPickup=true;else r.recipientPickup=true;if(r.donorPickup&&r.recipientPickup){r.status='Completed';l.status='Picked Up';}log('Recorded pickup confirmation');save();render();flash('Pickup confirmation recorded.');return;}if(a.startsWith('report-')){const lid=a.slice(7),reason=document.getElementById('report-reason')?.value.trim();if(!reason){flash('Describe the concern before sending.','error');return;}data.reports.push({id:id(),listingId:lid,by:user().org,reason,status:'Open',time:new Date().toISOString()});const l=data.listings.find(x=>x.id===lid);if(l&&l.status==='Available')l.status='Flagged for Review';log('Reported a listing concern');save();render();flash('Report sent to an administrator.');}});
