    document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-form="edit-listing"]'))return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f).entries()),u=user(),l=data.listings.find(x=>x.id===f.dataset.listingId&&x.donorId===u?.id);if(!u||u.accessApproved===false){flash('Your organization must be approved before editing listings.','error');return;}if(!l||!['Available','Expired'].includes(l.status)){flash('This listing can no longer be edited.','error');return;}const prepared=submittedDateTime(v,'prepared'),pickupStart=submittedDateTime(v,'pickupStart'),deadline=submittedDateTime(v,'deadline');if(!prepared||!pickupStart||!deadline){flash('Enter the prepared date/time, pickup start, and pickup deadline.','error');return;}if(new Date(deadline)<=new Date()){flash('Pickup deadline must be in the future.','error');return;}if(new Date(pickupStart)>=new Date(deadline)){flash('Pickup availability must start before the deadline.','error');return;}Object.assign(l,{item:v.item.trim(),photo:v.photoData||null,photoData:v.photoData||null,category:v.category,quantity:v.quantity.trim(),prepared,pickupStart,storage:v.storage,allergens:v.allergens.trim()||'Not specified',packaging:v.packaging.trim(),deadline,location:v.location.trim(),latitude:v.latitude?Number(v.latitude):null,longitude:v.longitude?Number(v.longitude):null,notes:v.notes.trim(),status:'Available'});log(`Updated food listing: ${l.item}`);save();location.hash=`listing/${l.id}`;flash('Listing updated and made available to verified recipients.');},true);
