    document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-form="admin-register"]'))return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f).entries());if(v.invite!=='LOCAL-ADMIN-2026'){flash('That administrator invite code is not valid.','error');return;}if(data.users.some(x=>x.email.toLowerCase()===v.email.trim().toLowerCase())){flash('An account with that email already exists.','error');return;}const u={id:id(),name:v.name.trim(),org:v.org.trim(),email:v.email.trim().toLowerCase(),password:v.password,role:'admin',verified:true};data.users.push(u);setCurrent(u.id);log(`Created ${roleName(u.role)} account`);save();location.hash='dashboard';flash('Administrator account created. This local demo is not secure for public use.');},true);
  window.RePlateApp={get data(){return data;},save,user,flash,log,render,esc,date,roleName};window.RePlateDirectory?.init();window.addEventListener('storage',event=>{if(event.key!==KEY||!event.newValue)return;try{const latest=JSON.parse(event.newValue);if(!latest||!Array.isArray(latest.users)||!Array.isArray(latest.listings))return;latest.current=sessionStorage.getItem(SESSION_KEY)||null;data=latest;window.RePlateDirectory?.init();if(!document.activeElement?.closest('form'))render();}catch{}});window.addEventListener('hashchange',render);if(!localStorage.getItem(KEY)||stateMigration)save();render();
